/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Dataset capture build (2026-11-03).  When set to 1:
 *   - the sampling thread records from the first good sample and never
 *     stops, so every boot is a continuous capture run;
 *   - REC lines go to the console only (no BLE decimation), and their
 *     format <c>REC,<t_ms>,<x_mg>,<y_mg>,<z_mg>,<gx>,<gy>,<gz></c> is
 *     exactly what tools/fall_threshold_analysis.py replays;
 *   - the fall alert UI is suppressed so a detection (including a false
 *     one, which is what we want to observe) cannot cover the screen
 *     for 15 s and interrupt the run.
 *
 * 0 for every normal image.  Build with 1 into a separate bin.
 */

#define AI_WATCH_CAPTURE_STREAM     0

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Activity classification */

#define AI_WATCH_MOTION_REST    0
#define AI_WATCH_MOTION_WALK    1
#define AI_WATCH_MOTION_RUN     2

/* Fall event kinds (BLE FALL_EVENT payload byte 0 and UI) */

#define AI_WATCH_FALL_NONE      0  /* no event */
#define AI_WATCH_FALL_CONFIRMED 1  /* countdown expired uncancelled */
#define AI_WATCH_FALL_CANCELLED 2  /* user cancelled the countdown */
#define AI_WATCH_FALL_TEST      3  /* manual test trigger */

/* Time the "Suspected fall" countdown runs before reporting (ms) */

/* Alert countdown. The capture build compresses it to 3 s: the state
 * machine ignores new gesture decisions while an alert is counting down,
 * and a 15 s window would swallow two 8 s-spaced dataset actions.  Only
 * the countdown length changes; the arming decision itself is untouched.
 */

#if AI_WATCH_CAPTURE_STREAM
#  define AI_WATCH_FALL_COUNTDOWN_MS    3000
#else
#  define AI_WATCH_FALL_COUNTDOWN_MS    15000
#endif

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* Fall state machine (NORMAL -> IMPACT -> ALARM -> NORMAL) */

enum ai_watch_fall_state_e
{
  FALL_STATE_NORMAL = 0,   /* monitoring */
  FALL_STATE_IMPACT,       /* spike seen, watching for stillness */
  FALL_STATE_ALARM         /* still + orientation flip: countdown to
                            * the "suspected fall" report */
};

/* Snapshot published for the Exercise UI (mutex-guarded, and mutated
 * only by the sampling thread - except fall_pending / fall_deadline_ms,
 * which the cancel/test helpers also touch, always under the mutex).
